from urllib.parse import urlparse, parse_qs

def _q(u):
    return {k: v[0] for k, v in parse_qs(urlparse(u).query).items()}

assert _q(add_utm("https://x.com/a?ref=nav", "nl", "email", "Promo")) == {"ref": "nav", "utm_source": "nl", "utm_medium": "email", "utm_campaign": "promo"}
